import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    edges = []
    for i in range(1, n):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append((v, i))
        adj[v].append((u, i))
        edges.append((u, v))

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    size = [0]*(n+1)
    heavy = [-1]*(n+1)

    def dfs(u):
        size[u] = 1
        max_size = 0
        for v, idx in adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                dfs(v)
                size[u] += size[v]
                if size[v] > max_size:
                    max_size = size[v]
                    heavy[u] = v

    dfs(1)

    head = [0]*(n+1)
    pos = [0]*(n+1)
    current_pos = 1

    def decompose(u, h):
        nonlocal current_pos
        head[u] = h
        pos[u] = current_pos
        current_pos += 1
        if heavy[u] != -1:
            decompose(heavy[u], h)
        for v, idx in adj[u]:
            if v != parent[u] and v != heavy[u]:
                decompose(v, v)

    decompose(1, 1)

    def lca(u, v):
        while head[u] != head[v]:
            if depth[head[u]] > depth[head[v]]:
                u = parent[head[u]]
            else:
                v = parent[head[v]]
        return u if depth[u] < depth[v] else v

    days = []
    edge_to_day = [0]*(n)
    day_to_edges = {}

    for i in range(n-1):
        u, v = edges[i]
        ancestor = lca(u, v)
        if ancestor == u or ancestor == v:
            days.append([i+1])
            day_to_edges[len(days)] = [i+1]
        else:
            found = False
            for d in range(1, len(days)+1):
                if ancestor in [pos[x] for x in day_to_edges[d]]:
                    days[d-1].append(i+1)
                    day_to_edges[d].append(i+1)
                    found = True
                    break
            if not found:
                days.append([i+1])
                day_to_edges[len(days)] = [i+1]

    print(len(days))
    for day in days:
        print(len(day), *day)

if __name__ == '__main__':
    main()
